package com.jcscllc.proxiscape.file;

import net.runelite.client.RuneLite;

import javax.sound.sampled.AudioSystem;
import javax.sound.sampled.DataLine;
import javax.sound.sampled.Line;
import javax.sound.sampled.Mixer;
import java.io.*;
import java.nio.file.Files;
import java.util.Scanner;

public class FileManager {

    private static final String PLUGIN_PATH = RuneLite.RUNELITE_DIR + "/proximity-chat/";

    public static void writeInfo(String fileName, Mixer.Info info) throws IOException {
        File dir = new File(PLUGIN_PATH);

        dir.mkdirs();

        File file = new File(PLUGIN_PATH + fileName);

        file.createNewFile();

        FileWriter writer = new FileWriter(file, false);

        writer.write(info.getName() + "\n");
        writer.write(info.getDescription() + "\n");
        writer.write(info.getVendor() + "\n");
        writer.write(info.getVersion() + "\n");

        writer.close();
    }

    public static Mixer.Info readInfo(String fileName, boolean isMic) throws FileNotFoundException {
        File file = new File(PLUGIN_PATH + fileName);

        if (!file.exists())
            return null;

        Scanner scanner = new Scanner(file);

        String name = scanner.nextLine();
        String description = scanner.nextLine();
        String vendor = scanner.nextLine();
        String version = scanner.nextLine();

        scanner.close();

        Mixer.Info[] mixers = AudioSystem.getMixerInfo();

        for (Mixer.Info mixerInfo : mixers) {
            Mixer mixer = AudioSystem.getMixer(mixerInfo);

            for (Line.Info lineInfo : isMic ? mixer.getTargetLineInfo() : mixer.getSourceLineInfo()) {
                if (lineInfo instanceof DataLine.Info)
                    if (mixerInfo.getName().equals(name) && mixerInfo.getDescription().equals(description) &&
                            mixerInfo.getVendor().equals(vendor) && mixerInfo.getVersion().equals(version))
                        return mixerInfo;

            }
        }

        return null;
    }
}

package com.jcscllc.proxiscape.overlay;

import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.*;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

@Singleton
public class ProxiScapeOverlay extends Overlay {

    private final Client client;

    private Map<String, Long> spoke;

    @Inject
    public ProxiScapeOverlay(Client client) {
        this.client = client;

        spoke = new ConcurrentHashMap<String, Long>();

        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    public void spoke(String name) {
        spoke.put(name, System.currentTimeMillis());
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        for (Player player : client.getPlayers()) {
            if (player == null || player == client.getLocalPlayer())
                continue;

            if (!shouldMark(player))
                continue;

            drawCircle(graphics, player);
        }

        return null;
    }

    private boolean shouldMark(Player player) {
        String name = player.getName();

        return spoke.get(name) != null && System.currentTimeMillis() - spoke.get(name) < 1000;
    }

    private void drawCircle(Graphics2D graphics, Player player) {
        LocalPoint lp = player.getLocalLocation();

        if (lp == null)
            return;

        Point canvasPoint = Perspective.localToCanvas(
                client,
                lp,
                client.getPlane(),
                player.getLogicalHeight() + 20
        );

        if (canvasPoint == null)
            return;

        int radius = 5;

        graphics.setColor(Color.GREEN);
        graphics.setStroke(new BasicStroke(3));
        graphics.setRenderingHint(
                RenderingHints.KEY_ANTIALIASING,
                RenderingHints.VALUE_ANTIALIAS_ON
        );

        // Draw circle centered on head
        graphics.drawOval(
                canvasPoint.getX() - radius,
                canvasPoint.getY() - radius,
                radius * 2,
                radius * 2
        );
    }
}

package com.jcscllc.proxiscape.voiceclient;

import com.jcscllc.proxiscape.ProxiScapePlugin;
import com.jcscllc.proxiscape.voiceclient.packet.PacketManager;
import com.jcscllc.proxiscape.voiceclient.sound.SoundManager;
import com.jcscllc.proxiscape.voiceclient.util.FriendlyByteBuf;
import lombok.Getter;

import java.io.IOException;
import java.net.DatagramPacket;
import java.net.DatagramSocket;
import java.net.SocketException;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.TimeUnit;

public class VoiceClient extends Thread {

    private static final int PACKET_BUFFER_SIZE = 4096;

    private final BlockingQueue<DatagramPacket> packetQueue;

    private final PacketProcessor packetProcessor;

    @Getter
    private ProxiScapePlugin plugin;

    @Getter
    private DatagramSocket socket;

    @Getter
    private PacketManager packetManager;

    @Getter
    private SoundManager soundManager;

    @Getter
    private KeepAlive keepAlive;

    @Getter
    private boolean running;

    public VoiceClient(ProxiScapePlugin plugin) throws SocketException {
        this.plugin = plugin;

        socket = new DatagramSocket();

        running = true;

        packetQueue = new LinkedBlockingQueue<DatagramPacket>();

        packetProcessor = new PacketProcessor();

        packetManager = new PacketManager(this);

        soundManager = new SoundManager(this);

        createKeepAlive();

        packetProcessor.start();
    }

    @Override
    public void run() {
        while (running) {
            byte[] buffer = new byte[PACKET_BUFFER_SIZE];
            DatagramPacket packet = new DatagramPacket(buffer, buffer.length);

            try {
                socket.receive(packet);

                packetQueue.add(packet);
            } catch (IOException e) {
                e.printStackTrace();
            }
        }

    }

    public void end() {
        running = false;

        keepAlive.running = false;

        packetProcessor.running = false;

        packetQueue.clear();

        packetManager.end();

        soundManager.end();

        if (socket != null)
            socket.close();
    }

    private class PacketProcessor extends Thread {
        private boolean running;

        public PacketProcessor() {
            running = true;

            setDaemon(true);
        }

        @Override
        public void run() {
            while (running) {
                try {
                    DatagramPacket packet = packetQueue.poll(10, TimeUnit.MILLISECONDS);

                    if (packet == null)
                        continue;

                    packetManager.read(packet.getSocketAddress(), FriendlyByteBuf.wrap(packet.getData()));
                } catch (Exception e) {
                    e.printStackTrace();
                }
            }
        }
    }

    public void createKeepAlive() {
        keepAlive = new KeepAlive();
    }

    public class KeepAlive extends Thread {

        private boolean running;

        public KeepAlive() {
            running = true;

            setDaemon(true);
        }

        @Override
        public void run() {
            while (running) {
                try {
                    Thread.sleep(3000);

                    if (ProxiScapePlugin.PLAYER_INFO != null && packetManager.isAuthenticated())
                        packetManager.writeKeepAlivePacket(ProxiScapePlugin.PLAYER_INFO[0] + "");
                } catch (Exception e) {
                    e.printStackTrace();
                }
            }
        }

        public void end() {
            running = false;
        }
    }

}

package com.jcscllc.proxiscape.voiceclient.packet;

import com.jcscllc.proxiscape.ProxiScapePlugin;
import com.jcscllc.proxiscape.voiceclient.VoiceClient;
import com.jcscllc.proxiscape.voiceclient.util.FriendlyByteBuf;
import lombok.Getter;

import java.net.DatagramPacket;
import java.net.InetSocketAddress;
import java.net.SocketAddress;
import java.util.HashMap;
import java.util.Map;

public class PacketManager {

    private static final int MAXIMUM_PACKET_SIZE = 4000;

    private static final String VOICE_SERVER_DOMAIN_USE = "proxiscape-use.jcsc-llc.com";

    private static final String VOICE_SERVER_DOMAIN_UK = "proxiscape-uk.jcsc-llc.com";

    private static final String VOICE_SERVER_DOMAIN_DE = "proxiscape-de.jcsc-llc.com";

    private static final String VOICE_SERVER_DOMAIN_AUS = "proxiscape-aus.jcsc-llc.com";

    private static final int VOICE_SERVER_PORT = 4545;

    private static final byte MAGIC_BYTE = (byte) 0b11111111;

    private static final long PACKET_TTL = 10_000L;

    private static final byte AUTHENTICATE_PACKET = 0x1;

    private static final byte AUTHENTICATE_ACK_PACKET = 0x2;

    private static final byte KEEP_ALIVE_PACKET = 0x3;

    private static final byte LOCATIONAL_VOICE_PACKET = 0x4;

    private static final byte STATIC_VOICE_PACKET = 0x5;

    private static final byte UPDATE_POSITION_PACKET = 0x6;

    private static final byte PING_PACKET = 0x7;

    private static final byte PONG_PACKET = 0x8;

    private static final byte NO_PACKET = 0x9;

    private final VoiceClient voiceClient;

    private InetSocketAddress sock;

    private boolean running;

    @Getter
    private boolean isAuthenticated;

    public PacketManager(VoiceClient voiceClient) {
        this.voiceClient = voiceClient;

        running = true;
    }

    public void createVoiceSocket(int worldType) {
        String voiceServer = VOICE_SERVER_DOMAIN_USE;

        switch (worldType) {
            case 1 :
                voiceServer = VOICE_SERVER_DOMAIN_UK;
                break;

            case 3 :
            case 10 :
            case 12 :
                voiceServer = VOICE_SERVER_DOMAIN_AUS;
                break;

            case 7 :
                voiceServer = VOICE_SERVER_DOMAIN_DE;
                break;

            default :
                voiceServer = VOICE_SERVER_DOMAIN_USE;
                break;
        }

        sock = new InetSocketAddress(voiceServer, VOICE_SERVER_PORT);
    }

    public void end() {
        running = false;
    }

    public void read(SocketAddress from, FriendlyByteBuf fbb) throws Exception {
        if (fbb.readByte() != MAGIC_BYTE) //Read magic byte
            return;

        int packetSequence = fbb.readShort(); //read sequence

        long packetTimestamp = fbb.readLong(); //Read timestamp of packet

        if (System.currentTimeMillis() - packetTimestamp > PACKET_TTL)
            return;

        byte type = fbb.readByte(); // read packet type

        switch (type) {
            case AUTHENTICATE_ACK_PACKET:
                voiceClient.createKeepAlive();
                voiceClient.getKeepAlive().start();
                isAuthenticated = true;
                break;

            case LOCATIONAL_VOICE_PACKET:
                String name = fbb.readUtf();

                int world = fbb.readInt();

                int x = fbb.readInt();

                int y = fbb.readInt();

                int plane = fbb.readInt();

                int length = fbb.readVarInt();

                byte[] opusIn = fbb.readBytes(length);

                voiceClient.getSoundManager().getSpeaker().queueLocationalSoundPacket(packetSequence, opusIn, name, world, x, y, plane);
                break;

            case STATIC_VOICE_PACKET:
                length = fbb.readVarInt();

                opusIn = fbb.readBytes(length);

                voiceClient.getSoundManager().getSpeaker().queueStaticSoundPacket(packetSequence, opusIn);
                break;

            case PONG_PACKET:
                isAuthenticated = true;
                break;

            case NO_PACKET:
                isAuthenticated = false;
                if (ProxiScapePlugin.PLAYER_INFO != null) {
                    voiceClient.getKeepAlive().end();
                    writeAuthenticatePacket(ProxiScapePlugin.PLAYER_INFO[0] + "", ProxiScapePlugin.PLAYER_INFO[1] + "", (int) ProxiScapePlugin.PLAYER_INFO[2], (int) ProxiScapePlugin.PLAYER_INFO[3], (int) ProxiScapePlugin.PLAYER_INFO[4]);
                }
                break;

            default:
                break;
        }
    }

    int sequence = 0;

    public void write(byte type, SocketAddress to, FriendlyByteBuf data) throws Exception {
        FriendlyByteBuf fbb = new FriendlyByteBuf(MAXIMUM_PACKET_SIZE);
        fbb.writeByte(MAGIC_BYTE); //Write magic byte

        fbb.writeShort((short) sequence);

        sequence = (sequence + 1) & 0xFFFF;

        fbb.writeLong(System.currentTimeMillis()); //Write timestamp
        fbb.writeByte(type); //Write type

        byte[] array = data.toByteArray();

        fbb.writeBytes(array, array.length); //Append data

        byte[] writable = fbb.toByteArray();

        voiceClient.getSocket().send(new DatagramPacket(writable, writable.length, to));
    }

    public void writeAuthenticatePacket(String hash, String username, int world, int x, int y) throws Exception {
        FriendlyByteBuf buf = new FriendlyByteBuf(MAXIMUM_PACKET_SIZE);
        buf.writeUtf(hash);
        buf.writeUtf(username);
        buf.writeInt(world);
        buf.writeInt(x);
        buf.writeInt(y);

        write(AUTHENTICATE_PACKET, sock, buf);
    }

    public void writeKeepAlivePacket(String hash) throws Exception {
        FriendlyByteBuf buf = new FriendlyByteBuf(MAXIMUM_PACKET_SIZE);
        buf.writeUtf(hash);

        write(KEEP_ALIVE_PACKET, sock, buf);
    }

    public void writePingPacket(String hash) throws Exception {
        FriendlyByteBuf buf = new FriendlyByteBuf(MAXIMUM_PACKET_SIZE);
        buf.writeUtf(hash);

        write(PING_PACKET, sock, buf);
    }

    public void writeUpdatePositionPacket(String hash, int world, int x, int y) throws Exception {
        FriendlyByteBuf buf = new FriendlyByteBuf(MAXIMUM_PACKET_SIZE);
        buf.writeUtf(hash);
        buf.writeInt(world);
        buf.writeInt(x);
        buf.writeInt(y);

        write(UPDATE_POSITION_PACKET, sock, buf);
    }

    public void writeLocationalVoiceData(String hash, int world, int x, int y, int plane, byte[] voiceData, int length) throws Exception {
        FriendlyByteBuf buf = new FriendlyByteBuf(MAXIMUM_PACKET_SIZE);
        buf.writeUtf(hash);
        buf.writeInt(world);
        buf.writeInt(x);
        buf.writeInt(y);
        buf.writeInt(plane);
        buf.writeVarInt(length);
        buf.writeBytes(voiceData, length);

        write(LOCATIONAL_VOICE_PACKET, sock, buf);
    }

}

